import * as THREE from './three.module.js';
export function createFireSystem(scene,{capacity=16}={}){
 const canvas=document.createElement('canvas');canvas.width=96;canvas.height=128;const g=canvas.getContext('2d'),glow=g.createRadialGradient(48,83,3,48,83,44);glow.addColorStop(0,'#fff7b5');glow.addColorStop(.2,'#ffc347');glow.addColorStop(.55,'#ff681b');glow.addColorStop(1,'#d8200200');g.fillStyle=glow;g.fillRect(0,0,96,128);g.fillStyle='#ff8a29';g.beginPath();g.moveTo(26,110);g.quadraticCurveTo(10,61,40,17);g.quadraticCurveTo(35,66,53,67);g.quadraticCurveTo(76,28,67,13);g.quadraticCurveTo(99,80,64,111);g.closePath();g.fill();
 const texture=new THREE.CanvasTexture(canvas),material=new THREE.SpriteMaterial({map:texture,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending});const pool=Array.from({length:capacity},()=>{const sprite=new THREE.Sprite(material);sprite.visible=false;sprite.scale.set(3.2,4.3,1);scene.add(sprite);return {sprite,id:'',expires:0,position:new THREE.Vector3()};});
 function ignite(id,position,duration=14000){let fire=pool.find(x=>x.sprite.visible&&x.id===id)||pool.find(x=>!x.sprite.visible)||pool.reduce((a,b)=>a.expires<b.expires?a:b);fire.id=id;fire.position.copy(position);fire.expires=performance.now()+duration;fire.sprite.visible=true;fire.sprite.position.copy(position).add(new THREE.Vector3(0,2,0));return true;}
 function extinguish(position,radius=180){let n=0;for(const fire of pool)if(fire.sprite.visible&&fire.position.distanceTo(position)<=radius){fire.sprite.visible=false;fire.id='';n++;}return n;}
 function update(now){for(const f of pool)if(f.sprite.visible){if(now>=f.expires){f.sprite.visible=false;f.id='';continue;}f.sprite.position.y=f.position.y+2+Math.sin(now*.009+f.position.x)*.2;f.sprite.material.rotation=Math.sin(now*.003+f.position.z)*.045;}}
 return {ignite,extinguish,update,dispose(){for(const f of pool)scene.remove(f.sprite);material.dispose();texture.dispose();}};
}
